# (first_word, last_word, kind, arabic, malay, ref)  -- indices into words.json
CUES = [
 (0, 1, 's', '', 'Hadis kesembilan:', ''),
 (2, 16, 'h', 'عَنْ أبي هُرَيرة رضي الله عنه قال: سَمِعتُ رَسولَ اللهِ ﷺ يقولُ:', 'Daripada Abu Hurairah Abdul Rahman bin Sakhar رضي الله عنه berkata: “Aku mendengar Rasulullah ﷺ bersabda:', ''),
 (17, 27, 'h', '«مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ، وَمَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ»', '‘Setiap yang aku larang kamu dari melakukannya, maka hendaklah kamu menjauhinya. Dan setiap yang aku perintahkan kamu dengannya, maka laksanakanlah daripadanya semampumu.', ''),
 (28, 39, 'h', '«فَإِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ»', 'Sesungguhnya perkara yang membinasakan umat sebelum kamu adalah banyaknya persoalan mereka dan perselisihan mereka terhadap nabi-nabi mereka.’”', 'Riwayat al-Bukhari dan Muslim — Hadis 40, no. 9'),
 (40, 53, 's', '', 'Perawi hadis ini ialah Abu Hurairah. Yang masyhur, beliau ialah Abdul Rahman bin Sakhar dari kabilah Daus, Yaman —', ''),
 (54, 62, 's', '', 'semoga Allah meredhainya dan meredhakannya. Beliau berhijrah pada awal tahun ketujuh Hijrah.', ''),
 (63, 73, 's', '', 'Tetapi bila beliau memeluk Islam tidak diketahui; yang pasti beliau berhijrah pada awal tahun ketujuh,', ''),
 (74, 81, 's', '', 'dan menyertai Perang Khaibar, yang berlaku pada awal tahun ketujuh.', ''),
 (82, 102, 's', '', 'Beliau perawi hadis Nabi ﷺ yang paling banyak; beliau meriwayatkan kira-kira lima ribu hadis — 5,374 hadis.', ''),
 (103, 115, 's', '', 'Beliau juga antara perawi al-Quran, antara perawi yang meriwayatkan Kitab Allah Tabaraka wa Ta‘ala.', ''),
 (116, 129, 's', '', 'Tiada seorang mukmin di muka bumi melainkan dia menyayanginya, dan sesiapa yang tidak menyayangi Abu Hurairah,', ''),
 (130, 141, 's', '', 'maka dalam hatinya ada kelemahan iman dan kekosongan. Oleh itu Nabi ﷺ bersabda', ''),
 (142, 150, 'h', '«اللَّهُمَّ حَبِّبْهُ إِلَى النَّاسِ وَحَبِّبِ النَّاسَ إِلَيْهِ»', 'kepada Abu Hurairah: “Ya Allah, jadikan dia dicintai oleh manusia dan jadikan manusia mencintainya.”', ''),
 (151, 162, 's', '', 'Maka Abu Hurairah berkata: Tiada mukmin di muka bumi melainkan dia mencintaiku,', ''),
 (163, 170, 's', '', 'kerana doa Nabi ﷺ untukku itu.', ''),
 (171, 183, 's', '', 'Beliau tidak menyertai fitnah — tidak dalam Perang Jamal, tidak dalam Siffin, dan tidak dalam Nahrawan.', ''),
 (184, 190, 's', '', 'Beliau tidak menyertai mana-mana peperangan itu.', ''),
 (191, 199, 's', '', 'Beliau wafat pada tahun 59 Hijrah dan dikebumikan di Baqi‘.', ''),
 (200, 209, 's', '', 'Nahrawan bukan sebahagian fitnah; ia peperangan yang hak seratus peratus,', ''),
 (210, 221, 's', '', 'tetapi fitnah itu ialah Jamal dan Siffin, dan ini bukan tempat untuk memperincikan perkara ini.', ''),
 (222, 238, 's', '', 'Sebab datangnya hadis: Abu Hurairah رضي الله عنه berkata: Rasulullah ﷺ berkhutbah kepada kami lalu bersabda:', ''),
 (239, 247, 'h', '«يَا أَيُّهَا النَّاسُ قَدْ فَرَضَ اللهُ عَلَيْكُمُ الْحَجَّ فَحُجُّوا»', '“Wahai manusia, Allah telah memfardukan haji ke atas kamu, maka tunaikanlah haji.”', ''),
 (248, 254, 'h', '«أَكُلَّ عَامٍ يَا رَسُولَ اللهِ؟»', 'Seorang lelaki bertanya: “Adakah setiap tahun, wahai Rasulullah?”', ''),
 (255, 276, 's', '', 'Maksudnya, adakah kita berhaji setiap tahun? Solat lima waktu sehari, puasa setiap tahun, zakat dikeluarkan setiap tahun — adakah haji juga begitu?', ''),
 (277, 283, 's', '', '“Adakah setiap tahun, wahai Rasulullah?”', ''),
 (284, 294, 's', '', 'Nabi ﷺ diam. Lelaki itu bercakap lalu mengulangi soalan:', ''),
 (295, 307, 's', '', '“Adakah setiap tahun, wahai Rasulullah?” — sedang Rasulullah ﷺ diam.', ''),
 (308, 316, 's', '', 'Kemudian dia bertanya kali ketiga: “Adakah setiap tahun, wahai Rasulullah?”', ''),
 (317, 329, 'h', '«لَوْ قُلْتُ نَعَمْ لَوَجَبَتْ، وَلَمَا اسْتَطَعْتُمْ»', 'Maka Rasulullah ﷺ bersabda: “Kalau aku katakan ya, nescaya ia menjadi wajib, dan kamu tidak akan mampu.”', ''),
 (330, 334, 'h', '«ذَرُونِي مَا تَرَكْتُكُمْ»', 'Kemudian baginda bersabda: “Biarkan aku selagi aku membiarkan kamu.”', ''),
 (335, 341, 's', '', 'Ini termasuk dalam firman Allah Tabaraka wa Ta‘ala:', ''),
 (342, 352, 'q', 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَسْـَٔلُوا۟ عَنْ أَشْيَآءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ', '“Wahai orang-orang yang beriman! Janganlah kamu bertanyakan (kepada Nabi) perkara-perkara yang jika diterangkan kepada kamu akan menyusahkan kamu…”', 'Surah al-Ma’idah, 5:101'),
 (353, 374, 's', '', 'Lalu baginda bersabda: “Biarkan aku selagi aku membiarkan kamu.” Aku tidak mengatakan setiap tahun — mengapa kamu tanya soalan-soalan ini? Mungkin aku akan katakan setiap tahun, lalu manusia tidak mampu melakukannya.', ''),
 (375, 386, 'h', '«إِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ وَاخْتِلَافُهُمْ عَلَى أَنْبِيَائِهِمْ»', '“Sesungguhnya yang membinasakan orang sebelum kamu ialah banyaknya soalan mereka dan perselisihan mereka terhadap nabi-nabi mereka.', ''),
 (387, 397, 'h', '«مَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، وَمَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ»', 'Apa yang aku perintahkan kamu, laksanakanlah semampumu; apa yang aku larang kamu, jauhilah.”', ''),
 (398, 404, 's', '', 'Lalu baginda menyebut hadis itu: “Biarkan aku selagi aku membiarkan kamu…”', ''),
 (405, 425, 's', '', 'Dikatakan penanya itu ialah al-Aqra‘ bin Habis — al-Aqra‘ bin Habis daripada Bani Tamim — dialah yang bertanya kepada Nabi ﷺ', ''),
 (426, 439, 's', '', 'soalan ini, iaitu “adakah setiap tahun?”, mengandaikan sesuatu masalah kepada Nabi ﷺ.', ''),
 (440, 447, 'h', '«إِنَّمَا أَهْلَكَ الَّذِينَ مِنْ قَبْلِكُمْ كَثْرَةُ مَسَائِلِهِمْ»', '“Sesungguhnya yang membinasakan orang sebelum kamu ialah banyaknya soalan mereka.”', ''),
 (448, 454, 's', '', 'Banyaknya soalan mereka — soalan-soalan ini terbahagi kepada dua bahagian:', ''),
 (455, 464, 's', '', 'sama ada bertanya soalan atau meminta harta, iaitu meminta wang.', ''),
 (465, 489, 's', '', 'Tetapi yang masyhur di sini, “banyak soalan mereka”, ialah bertanya dengan kata-kata: apa hukumnya begini, apa yang perlu dibuat, jika berlaku begini, dan seumpamanya.', ''),
 (490, 499, 's', '', 'Soalan-soalan ini terbahagi kepada dua: sama ada masalah yang sudah berlaku,', ''),
 (500, 516, 's', '', 'atau masalah yang belum berlaku. Jika ia sudah berlaku, urusannya jelas: seseorang bertanya supaya dia mengetahui yang benar daripada yang batil.', ''),
 (517, 538, 's', '', 'Zaid bin Thabit رضي الله عنه, begitu juga Ibn Umar, dan ini dinukilkan juga daripada Ubai bin Ka‘ab — mereka tidak suka soalan-soalan andaian,', ''),
 (539, 561, 's', '', 'iaitu seseorang berkata: kalau berlaku begini, apa patut aku buat? Mereka jawab: apabila ia berlaku, datanglah bertanya — begitulah jawapan mereka.', ''),
 (562, 567, 's', '', 'Jangan mengandaikan masalah-masalah, jangan mengandaikan masalah-masalah.', ''),
 (568, 584, 's', '', 'Seorang lelaki datang kepada Ibn Umar lalu bertanya: “Bagaimana jika aku datang ke Hajar (Aswad) dan mendapati kesesakan?” Beliau menjawab: “Ciumlah Hajar.”', ''),
 (585, 594, 's', '', 'Lelaki itu bertanya: “Jika aku mendapati kesesakan, apa yang patut aku lakukan?” Ibn Umar menjawab: “Tinggalkan soalan ini di Yaman.”', ''),
 (595, 608, 's', '', 'Dia bertanya lagi: “Bagaimana jika ada kesesakan?” Katanya: “Tinggalkan ‘bagaimana jika’ itu di Yaman. Apabila datang, ciumlah Hajar.”', ''),
 (609, 623, 's', '', 'Adakah kamu sekarang mendapati kesesakan atau tidak? Tinggalkan; apabila kamu mendapati kesesakan, bertanyalah. Maka jangan mengandaikan masalah-masalah.', ''),
 (624, 631, 's', '', 'Jangan bertanya — sebahagian orang andaiannya sangat pelik.', ''),
 (632, 654, 's', '', 'Oleh itu para ulama membahagikan manusia kepada beberapa golongan dalam hal mengandaikan masalah. Ada yang menutup terus pintu persoalan: tiada andaian; jika ada kes sebenar, kami jawab.', ''),
 (655, 669, 's', '', 'Ketika itu dikatakan: orang seperti mereka sedikit fiqhnya, kerana mereka tidak mengandaikan masalah — apabila ia berlaku, bagaimana kita hendak menjawabnya?', ''),
 (670, 679, 's', '', 'Ada pula yang sangat meluas dalam menjana masalah — mengandaikan perkara-perkara yang kadang-kadang', ''),
 (680, 691, 's', '', 'tidak mungkin berlaku, tidak mungkin berlaku. Dia mengandaikan satu masalah, kemudian satu masalah lagi.', ''),
 (692, 705, 's', '', 'Baiklah, jika berlaku begini, jika seorang (gadis) berusia tiga tahun melahirkan anak, apa hukumnya? Masuk akal ke?', ''),
 (706, 719, 's', '', '“Andaikan, andaikan…” dan dia mula mengandaikan masalah yang tidak mungkin berlaku, tidak mungkin berlaku. Andaikan', ''),
 (720, 741, 's', '', 'seorang lelaki mengandung, bagaimana, apa dia nak buat? Dia mengandaikan seorang lelaki didatangi haid — tiada lelaki begitu — dia mula mengandaikan masalah yang tidak mungkin berlaku.', ''),
 (742, 761, 's', '', 'Inilah yang dibenci oleh ulama dan mereka melarangnya, kerana ia masalah andaian yang pada asalnya tidak boleh diterima, dan sebahagian orang menjadi berlebih-lebihan dalam mengandaikan masalah.', ''),
 (762, 782, 's', '', 'Golongan ketiga ialah yang bersederhana: dia mengandaikan masalah, tetapi masalah yang mungkin berlaku, lalu dia menetapkan penyelesaiannya sekiranya ia berlaku.', ''),
 (783, 799, 's', '', 'Adapun soalan-soalan yang dilarang, berdasarkan sabda Nabi ﷺ “banyaknya soalan mereka”: pertama, soalan untuk menyusahkan dan memperdalam (yang tidak perlu),', ''),
 (800, 810, 's', '', 'ini dilarang, seperti soalan Bani Israil kepada Nabi Musa عليه السلام', ''),
 (811, 819, 's', '', 'ketika (baginda berkata) “Allah memerintahkan kamu menyembelih seekor lembu”: “Lembu apa ia?” Dijawab:', ''),
 (820, 829, 's', '', '“Tidak tua dan tidak muda.” “Apa warnanya?” “Kuning.” “Apakah ia?” sekali lagi:', ''),
 (830, 838, 's', '', '“Engkau belum menjelaskan kepada kami.” Inilah soalan-soalan yang menyusahkan — soalan-soalan yang menyusahkan.', ''),
 (839, 843, 's', '', 'Oleh itu mereka memberat-beratkan, maka Allah memberatkan mereka.', ''),
 (844, 863, 's', '', 'Kadang-kadang soalan yang tiada faedah dan tiada keperluan — dia hanya mahu bercakap, mahu berkata sesuatu.', ''),
 (864, 880, 's', '', 'Kadang-kadang itu juga dilarang. Begitu juga soalan yang bertujuan memperolok-olok dan mengejek; sesetengah orang bertanya dengan cara memperolok-olok', ''),
 (881, 899, 's', '', 'dan mengejek, seperti kaum Nuh terhadap Nuh ‘alaihissalam ketika beliau membina bahtera; setiap kali sekumpulan pembesar kaumnya melaluinya mereka mengejeknya, lalu berkata:', ''),
 (900, 918, 's', '', '“Dahulu engkau seorang nabi, sekarang engkau menjadi tukang kayu! Beberapa hari lalu engkau mengatakan engkau nabi, sekarang engkau jadi tukang kayu; engkau membina kapal.”', ''),
 (919, 931, 's', '', 'Maka soalan mereka itu bertujuan memperolok-olok dan mengejek; ini juga soalan yang dilarang.', ''),
 (932, 944, 's', '', 'Masalah yang belum berlaku: kita katakan, jika ia dijangka dan mungkin berlaku, tidak mengapa;', ''),
 (945, 955, 's', '', 'adapun andaian perkara yang mustahil, maka asalnya ialah seseorang tidak bertanya tentangnya.', ''),
 (956, 978, 's', '', 'Bertanya tentang rahsia qada dan qadar, dan perkara yang Allah sembunyikan daripada kita, Maha Suci dan Maha Tinggi Dia — manusia juga tidak akan sampai kepada sesuatu kesimpulan padanya, maka tidak boleh bertanya tentangnya.', ''),
 (979, 988, 's', '', 'Bertanya tentang sifat syurga yang sebenar, hakikat perkara-perkara itu — Allah Ta‘ala berfirman tentangnya:', ''),
 (989, 1001, 'h', '«مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ»', '“Apa yang tidak pernah dilihat oleh mata, tidak pernah didengar oleh telinga, dan tidak pernah terlintas di hati manusia.”', ''),
 (1002, 1019, 's', '', 'Aku menjangkakan syurga begini — Dia katakan kepadamu: tidak pernah terlintas di hati manusia. Kamu manusia, bukan? Kamu manusia.', ''),
 (1020, 1029, 's', '', 'Allah Subhanahu wa Ta‘ala berfirman: tidak pernah terlintas di hati manusia.', ''),
 (1030, 1045, 's', '', 'Jika mereka kata “terlintas di fikiranmu”, ia bukan begitu, kerana Dia berfirman: tidak terlintas di hati manusia.', ''),
 (1046, 1059, 's', '', 'Semua ini soalan yang dilarang. Adapun bertanya untuk ilmu dan amalan, maka ia dituntut. Allah Tabaraka wa Ta‘ala berfirman:', ''),
 (1060, 1066, 'q', 'فَسْـَٔلُوٓا۟ أَهْلَ ٱلذِّكْرِ إِن كُنتُمْ لَا تَعْلَمُونَ', '“…Oleh itu bertanyalah kamu (wahai golongan musyrik) kepada orang-orang yang berpengetahuan ugama jika kamu tidak mengetahui.”', 'Surah an-Nahl, 16:43'),
 (1067, 1084, 'h', '«نِعْمَ النِّسَاءُ نِسَاءُ الْأَنْصَارِ، لَمْ يَمْنَعْهُنَّ الْحَيَاءُ مِنَ التَّفَقُّهِ فِي الدِّينِ»', 'Nabi ﷺ bersabda: “Sebaik-baik wanita ialah wanita Ansar; rasa malu tidak menghalang mereka daripada mendalami agama.”', ''),
 (1085, 1091, 's', '', 'Dan bertanya itu separuh ilmu; bertanya dengan baik itu separuh ilmu.', ''),
 (1092, 1100, 's', '', 'Ibn Abbas ditanya: Bagaimana engkau memperoleh ilmu? Jawabnya: dengan lidah yang banyak bertanya', ''),
 (1101, 1106, 's', '', 'dan hati yang berakal — dengan lidah yang banyak bertanya dan hati yang berakal.', ''),
 (1107, 1116, 's', '', 'Maka inilah soalan yang dituntut dan diterima, bahkan dipuji di sisi Allah Tabaraka wa Ta‘ala.', ''),
 (1117, 1134, 'h', '«مَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ»', 'Sabdanya: “Apa yang aku larang kamu daripadanya, maka jauhilah.” Semua larangan mampu ditinggalkan, kerana larangan itu hanyalah meninggalkan semata-mata; tiada sesuatu pun yang perlu kamu keluarkan,', ''),
 (1135, 1144, 's', '', 'tidak perlu membayar wang dan tidak perlu mengerahkan usaha — ia sekadar meninggalkan.', ''),
 (1145, 1157, 's', '', 'Oleh itu baginda bersabda “apa yang aku larang kamu, jauhilah”, sedangkan perintah — apa baginda sabdakan? “Laksanakan semampumu.”', ''),
 (1158, 1177, 's', '', 'Tidak dikatakan dalam larangan “tinggalkan sebahagiannya semampumu”, kerana ia meninggalkan semata-mata tanpa sebarang usaha. Tetapi perintah, kadang-kadang seseorang tidak mampu.', ''),
 (1178, 1183, 'h', '«صَلِّ قَائِمًا، فَإِنْ لَمْ تَسْتَطِعْ فَقَاعِدًا»', '“Solatlah sambil berdiri; jika tidak mampu, maka sambil duduk.”', ''),
 (1184, 1199, 'q', 'إِذَا قُمْتُمْ إِلَى ٱلصَّلَوٰةِ فَٱغْسِلُوا۟ وُجُوهَكُمْ … فَلَمْ تَجِدُوا۟ مَآءً فَتَيَمَّمُوا۟', 'Berwuduk bagi yang bangun tidur: “…apabila kamu hendak mengerjakan sembahyang (padahal kamu berhadas kecil), maka (berwuduklah) iaitu basuhlah muka kamu…” Dan di akhirnya: “…sedang kamu tidak mendapat air (untuk berwuduk dan mandi), maka hendaklah kamu bertayamum…”', 'Surah al-Ma’idah, 5:6'),
 (1200, 1207, 's', '', 'Perintah itu kadang-kadang tidak mampu dilakukan, lalu beralih kepada yang lebih mudah.', ''),
 (1208, 1222, 's', '', 'Tetapi larangan, tiada padanya (usaha); maka tinggalkanlah, kerana ia meninggalkan semata-mata yang tiada padanya pengorbanan.', ''),
 (1223, 1233, 's', '', 'Perhatikan kata-kata Nabi ﷺ, yang dikurniakan jawami‘ul kalim (kata-kata ringkas yang padat makna):', ''),
 (1234, 1243, 'h', '«مَا أَمَرْتُكُمْ بِهِ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ، وَمَا نَهَيْتُكُمْ عَنْهُ فَاجْتَنِبُوهُ»', '“Apa yang aku perintahkan kamu, laksanakanlah semampumu; apa yang aku larang kamu, jauhilah.”', ''),
 (1244, 1254, 's', '', 'Segera. Ada larangan yang diberi rukhsah, seperti memakan bangkai. Katakanlah: ‘Sesungguhnya yang diharamkan…’ —', ''),
 (1255, 1267, 'q', 'قُل لَّآ أَجِدُ فِى مَآ أُوحِىَ إِلَىَّ مُحَرَّمًا عَلَىٰ طَاعِمٍ يَطْعَمُهُۥٓ إِلَّآ أَن يَكُونَ مَيْتَةً', '“Katakanlah (wahai Muhammad): ‘Aku tidak dapati dalam apa yang telah diwahyukan kepadaku, sesuatu yang diharamkan bagi orang yang hendak memakannya melainkan kalau benda itu bangkai…’”', 'Surah al-An‘am, 6:145'),
 (1268, 1275, 's', '', 'Memakan bangkai itu haram. Tetapi jika seseorang terpaksa,', ''),
 (1276, 1279, 'q', 'إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ', '“…kecuali apa yang kamu terpaksa memakannya.”', 'Surah al-An‘am, 6:119'),
 (1280, 1289, 's', '', 'Jika seseorang terpaksa memakan bangkai, maka tiada halangan.', ''),
 (1290, 1298, 's', '', 'Maka larangan-larangan ini dibenarkan ketika darurat — dibenarkan ketika darurat.', ''),
 (1299, 1308, 's', '', 'Sama ada ia haram pada zatnya atau haram kerana sebab lain, dibenarkan ketika ada keperluan.', ''),
 (1309, 1319, 's', '', 'Seseorang tercekik makanan dan dia tidak ada apa-apa melainkan arak; adakah dibolehkan dia minum arak', ''),
 (1320, 1332, 's', '', 'supaya suapan itu turun? Boleh, dibolehkan dia minum arak supaya tidak mati kerana tercekik.', ''),
 (1333, 1344, 's', '', 'Ada yang bertanya: ‘Mengapa dia berada di tempat yang ada arak?’ Memang benar, tetapi andaikan dia berada di situ.', ''),
 (1345, 1355, 's', '', 'Yang penting, dia dibenarkan minum arak untuk menurunkan makanan yang menyekat kerongkongnya.', ''),
 (1356, 1385, 's', '', 'Dan dengan rahmat Allah Tabaraka wa Ta‘ala, para ulama berkata: tiada yang haram bersama darurat; mana-mana darurat membolehkan perkara yang dilarang dengan serta-merta — sebarang perkara haram dibolehkan ketika darurat. Allah Tabaraka wa Ta‘ala berfirman:', ''),
 (1386, 1395, 'q', 'وَقَدْ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيْكُمْ إِلَّا مَا ٱضْطُرِرْتُمْ إِلَيْهِ', '“…padahal Allah telah menerangkan satu persatu kepada kamu apa yang diharamkanNya atas kamu, kecuali apa yang kamu terpaksa memakannya…”', 'Surah al-An‘am, 6:119'),
 (1396, 1416, 's', '', 'Sabdanya “maka jauhilah”, dan baginda tidak bersabda “maka tinggalkanlah”, kerana menjauhi lebih tegas; menjauhi ialah menghindari — bukan sekadar tidak melakukan, tetapi jauhilah, jangan hampiri.', ''),
 (1417, 1431, 'h', '«مَنْ حَامَ حَوْلَ الْحِمَى يُوشِكُ أَنْ يَرْتَعَ فِيهِ»', 'Sabda Nabi ﷺ: “Sesiapa yang berlegar-legar di sekitar kawasan larangan, hampir-hampir dia memasukinya.”', ''),
 (1432, 1441, 's', '', 'Bukan sekadar jangan lakukan, bahkan jauhilah — iaitu menjauhkan diri daripadanya.', ''),
 (1442, 1455, 's', '', 'Baiklah, dalam perkara umum ini, ia datang untuk memelihara lima perkara pokok (al-kulliyyat al-khams) yang semua syariat datang untuk memeliharanya:', ''),
 (1456, 1468, 's', '', 'memelihara agama, nyawa, keturunan — iaitu maruah — harta dan akal. Kelima-lima perkara ini,', ''),
 (1469, 1481, 's', '', 'semua syariat sepakat memeliharanya, dan larangan datang untuk menghalang pencerobohan, gangguan atau pelanggaran', ''),
 (1482, 1490, 's', '', 'ke atas lima perkara besar ini: agama, akal, keturunan dan harta.', ''),
 (1491, 1502, 's', '', 'Maka manusia mengenali nilai syariat ini, yang sesungguhnya — Allah Tabaraka (wa Ta‘ala) berfirman tentangnya:', ''),
 (1503, 1513, 'q', 'ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَـٰمَ دِينًا', '“Pada hari ini, Aku telah sempurnakan bagi kamu ugama kamu, dan Aku telah cukupkan nikmatKu kepada kamu, dan Aku telah redakan Islam itu menjadi ugama untuk kamu.”', 'Surah al-Ma’idah, 5:3'),
 (1514, 1522, 'h', '«إِذَا أَمَرْتُكُمْ بِأَمْرٍ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ»', '“Apabila aku memerintahkan kamu dengan sesuatu, laksanakanlah semampumu.”', ''),
 (1523, 1542, 's', '', 'Ketidakmampuan melaksanakan kewajipan kadang-kadang menggugurkan semuanya, dan kadang-kadang menggugurkan sebahagiannya, mengikut kemampuan.', ''),
 (1543, 1547, 's', '', 'Seseorang yang tidak mampu membaca Fatihah:', ''),
 (1548, 1564, 's', '', 'Seorang lelaki datang kepada Nabi ﷺ lalu berkata: “Wahai Rasulullah, aku tidak pandai membaca Fatihah, aku tidak pandai” —', ''),
 (1565, 1571, 's', '', 'seorang yang baru Islam, tidak mengenali Fatihah langsung.', ''),
 (1572, 1595, 'h', '«قُلْ: سُبْحَانَ اللهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ»', 'Maka Nabi ﷺ bersabda kepadanya: “Katakanlah: Maha Suci Allah, segala puji bagi Allah, tiada tuhan melainkan Allah, Allah Maha Besar, dan tiada daya dan kekuatan melainkan dengan Allah.”', ''),
 (1596, 1608, 's', '', 'sebagai ganti Fatihah. Tetapi jika seseorang mampu membaca sebahagian Fatihah,', ''),
 (1609, 1617, 'q', 'ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ مَـٰلِكِ يَوْمِ ٱلدِّينِ', '“Segala puji tertentu bagi Allah, Tuhan yang memelihara dan mentadbirkan sekalian alam. Yang Maha Pemurah, lagi Maha Mengasihani. Yang Menguasai pemerintahan hari Pembalasan (hari Akhirat).”', 'Surah al-Fatihah, 1:2–4'),
 (1618, 1637, 's', '', '“Iyyaka…” — bagi selebihnya, kita katakan: bacalah apa yang kamu hafal, kemudian gantikan selebihnya dengan tasbih, tahlil dan takbir, Allah Subhanahu wa Ta‘ala.', ''),
 (1638, 1650, 's', '', 'Apa yang tidak mampu kamu lakukan, lakukan setakat yang mampu; apa yang langsung tidak mampu, semuanya gugur.', ''),
 (1651, 1654, 's', '', 'Dan segala puji bagi Allah, Tuhan sekalian alam.', ''),
]
